<?php
declare(strict_types=1);
namespace Nerozon\Questionnaire;
final class SubmitQuestionnaire{public function __construct(private QuestionnaireRepository $repository){}public function execute(array $c):array{$id=$c['questionnaire_id']??null;$v=$c['questionnaire_version']??null;$answers=$c['answers']??null;if($id!==QuestionnaireDefinition::ID)throw new UnsupportedQuestionnaire('Unsupported questionnaire');if($v!==QuestionnaireDefinition::VERSION)throw new UnsupportedQuestionnaireVersion('Unsupported questionnaire version');if(!is_array($answers))throw new InvalidQuestionnaireSubmission('answers must be array');$s=new QuestionnaireSubmission(self::uuidV4(),QuestionnaireDefinition::ID,QuestionnaireDefinition::VERSION,QuestionnaireDefinition::SCHEMA_VERSION,new \DateTimeImmutable('now',new \DateTimeZone('UTC')),QuestionnaireDefinition::normalizeAnswers($answers));$this->repository->save($s);return ['accepted'=>true];}private static function uuidV4():string{$d=random_bytes(16);$d[6]=chr((ord($d[6])&15)|64);$d[8]=chr((ord($d[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($d),4));}}
